<script setup lang="ts">
import UiInput from '../UiInput.vue';
import ServerTabBar from '../ServerTabBar.vue';
import MetricValue from '../MetricValue.vue';
import RelativeDate from '../RelativeDate.vue';
import {ref,watch,onUnmounted,onActivated,onDeactivated,computed} from 'vue';
import {call,preview} from '../../api';
import {useConfigAutosave} from '../../useConfigAutosave';
import type { ConnectorConfig, MonitoringValues } from '../../types';

interface PgConfig extends ConnectorConfig {database:string}
interface PgMetrics {connections:number;maxConnections:number;reservedConnections:number;active:number;longQueries:number;longestQuerySeconds:number;idleTransactions:number;blocked:number;maxWaitSeconds:number;blockers:{pid:number;blockers:number[]}[];streaming:number;replicationUnknown:number;replicaBacklogBytes:number|null;receiver:number;replayBacklogBytes:number|null;replayPaused:boolean;slotRetainedBytes:number|null;inactiveSlots:number;autovacuumWorkers:number;xidAge:number;deadlocks:number;rollbacks:number}
interface PgSummary {id:string;at:number;bytesReceived:number;data:{detected:boolean;connected:boolean;coverage:boolean;issues:string[];durationMs:number;meta:{version:number;generation:number;fullStats:boolean;superuser:boolean;trackActivities:boolean;trackCounts:boolean;recovery:boolean}|null;metrics:PgMetrics|null};findings:{key:string;title:string;severity:string;value:number}[]}
interface PgView {monitoring?:MonitoringValues;config:PgConfig;summary:PgSummary|null;evidence:PgSummary[];fresh:boolean;error:string|null;nextCheck:number;status:string}

const props=defineProps<{serverId:string;now:number;kind?:string;refreshKey?:string;instanceId?:string;displayName?:string}>();const emit=defineEmits<{updated:[]}>();
const view=ref<PgView>(),error=ref(''),busy=ref(false),dirty=ref(false);
const config=ref<PgConfig>({enabled:false,endpoint:'/var/run/postgresql',port:5432,database:'postgres',user:'',intervalSeconds:180,expectedPeers:0,expectReplica:false});
const m=computed(()=>view.value?.summary?.data.metrics),meta=computed(()=>view.value?.summary?.data.meta);
const activityKnown=computed(()=>!view.value?.summary?.data.issues.includes('activity_incomplete'));
const countsKnown=computed(()=>!view.value?.summary?.data.issues.includes('counters_disabled'));
let revision=0,active=true;onActivated(()=>{active=true;void load();});onDeactivated(()=>{active=false;revision++;});
const issues:Record<string,string>={endpoint_ambiguous:'We’ve got a few listeners, and you can manually select your local address and port',endpoint_not_local:'PostgreSQL local address and port not confirmed',profile_disabled:'Diagnostic connection not enabled',psql_missing:'The server does not have /usr/bin/psql; packages are not automatically installed',unsupported_version:'PostgreSQL version outside supported range 14–18',read_all_stats_required:'The role is not available pg_read_all_stats: statistics of other people’s sessions are not confirmed',activity_incomplete:'Activity tracking turned off or part of sessions hidden',counters_disabled:'Cumulator counters off',lock_wait_age_unknown:'The age of some blockage expectations is unknown',replication_position_unknown:'Part of WAL’s positions unknown',query_timeout:'Time to Read Statistics Exceeded',query_output_limit:'Response limit exceeded',connection_or_query_denied:'Connecting or reading statistics is not allowed; check the role, CONNECT, peer/.pgpass and endpoint availability',instance_changed:'DB connection changed during collection',collection_failed:'Statistical collection incomplete'};
const statuses:Record<string,string>={healthy:'Available checks are normal',warning:'There is a deviation or confirmation of recovery is expected',critical:'Critical deviation',unknown:'Condition unconfirmed',not_detected:'PostgreSQL not detected by standard checks'};
const tone=computed(()=>({healthy:'ok',warning:'warn',critical:'crit'} as Record<string,string>)[view.value?.status??'']??'');
const scope = () => ({id:props.serverId,kind:props.kind??'postgresql',...(props.instanceId?{instanceId:props.instanceId}:{})});
async function load(){const rev=++revision;try{const result=await call<PgView>('service_summary',scope());if(rev!==revision)return;view.value=result;if(!dirty.value)config.value={...result.config};}catch(e){if(rev===revision)error.value=String(e);}}
watch(()=>[props.serverId,props.instanceId],()=>{view.value=undefined;dirty.value=false;error.value='';void load();},{immediate:true});watch(()=>[props.now,props.refreshKey],()=>{if(active&&!document.hidden&&!busy.value)void load();});onUnmounted(()=>revision++);
const autosave=useConfigAutosave({command:'configure_service',scope,value:()=>config.value,dirty,error,saved:async()=>{await load();emit('updated');}});
async function act(save=false){if(save){await autosave.submit();return;}busy.value=true;error.value='';try{await call('refresh_service',scope());await load();emit('updated');}catch(e){error.value=String(e);}finally{busy.value=false;}}
function bytes(n:number|null|undefined){return n==null?'unknown':`${(n/1048576).toFixed(1)} MiB`;}
</script>
<template><section class="pg"><ServerTabBar :title="displayName??'PostgreSQL'" :busy="busy" :disabled="preview||view?.monitoring?.enabled===false" @refresh="act()">
  <span class="tag" :class="tone">{{ view?.status==='unknown' && view.summary?.data.detected && !view.config.enabled ? 'Diagnosis off' : statuses[view?.status??'unknown'] }}</span>
  <RelativeDate :at="view?.summary?.at" empty="untested"/>
  <template #actions><slot name="actions"/></template>
</ServerTabBar>
<slot name="before-content"/>
<p v-if="view?.monitoring?.enabled===false" class="notice">Monitoring is off. Execution settings are in the section “Monitoring”.</p><p v-if="error||view?.error" role="alert" class="problem">{{error||view?.error}}</p>

<template v-if="view?.summary"><p v-if="meta" class="version">PostgreSQL {{Math.floor(meta.version/10000)}} · {{meta.recovery?'standby / recovery':'primary'}} · session statistics: {{meta.fullStats?'available':'inaccessible'}}</p><p v-if="meta?.superuser" class="notice">The connection uses a superuser. A separate diagnostic role is preferred for monitoring.</p>
<template v-if="m"><div class="metrics"><div><small>Client connections</small><strong><MetricValue :value="m.connections" :precision="0"/> / <MetricValue :value="m.maxConnections-m.reservedConnections" :precision="0"/></strong><small>Normal limit; reserved {{m.reservedConnections}}</small></div><div><small>Active/Requests More Than 60 S</small><strong><MetricValue :value="activityKnown?m.active:null" :precision="0"/> / <MetricValue :value="activityKnown?m.longQueries:null" :precision="0"/></strong><small>Maximum age {{activityKnown?m.longestQuerySeconds.toFixed(1)+' s':'unknown'}}</small></div><div><small>Blocked sessions</small><strong><MetricValue :value="m.blocked" :precision="0"/></strong><small>Maximum waiting time {{view.summary.data.issues.includes('lock_wait_age_unknown')?'unknown':m.maxWaitSeconds.toFixed(1)+' s'}}</small></div><div><small>Idle-transactions more than 300 seconds</small><strong><MetricValue :value="activityKnown?m.idleTransactions:null" :precision="0"/></strong></div></div>
<div v-for="b in m.blockers" :key="b.pid" class="row">PID {{b.pid}} waiting for PID {{b.blockers.join(', ')||'vaguely'}}<small>Up to 5 waiting, up to 8 blocking; 0 means prepared transaction</small></div><details class="help"><summary>What data is collected</summary><p>Request texts, table data, customer names and passwords are not transmitted.</p></details>
<div class="row">Streaming connections: {{m.streaming}} · WAL receiver: {{m.receiver}}</div><div class="row">{{meta?.recovery?'Receive → replay':'Primary → replay'}}: {{bytes(meta?.recovery?m.replayBacklogBytes:(m.replicationUnknown?null:m.replicaBacklogBytes))}}</div><details class="help"><summary>How to Read Replication Delay</summary><p>The WAL backlog is measured in bytes. The time from the last transaction is not considered a delay: an idle replica can be functional. Unknown positions are not zero.</p></details><div class="row">Replay {{m.replayPaused?'suspended':'suspended'}} · slot-slot {{m.inactiveSlots}} · maximum retention of WAL {{bytes(m.slotRetainedBytes)}}</div><div class="row">Autovacuum workers: {{m.autovacuumWorkers}} · maximum age of frozen XID: {{m.xidAge}}<small>Catalog summary; VACUUM/ANALYZE does not start</small></div><div class="row">Deadlocks: {{countsKnown?m.deadlocks:'unknown'}} · rollback: {{countsKnown?m.rollbacks:'unknown'}}<small>DB accumulator counters, not the number of new events per cycle</small></div></template>
<div v-for="f in view.summary.findings" :key="f.key" class="problem">{{f.title}} · {{f.value}}</div><details class="help"><summary>When an incident is created</summary><p>Threshold deviations are confirmed by two observations at least a minute apart. Missing permissions or data cannot confirm recovery. Background collection works without AI; confirmed incidents use the automatic investigation budget.</p></details><details v-if="view.evidence.length"><summary>Evidence of open incidents</summary><article v-for="e in view.evidence" :key="e.id"><p><RelativeDate :at="e.at"/> · {{e.id}}</p><p v-for="f in e.findings" :key="f.key">{{f.title}} · {{f.value}}</p></article></details><small>Summary {{view.summary.bytesReceived}} bytes · collection {{view.summary.data.durationMs}} ms. SSH overheads are accounted for separately.</small><details v-if="!view.summary.data.coverage || view.summary.data.issues.length" class="quality"><summary>What’s tested</summary><ul><li v-if="!view.summary.data.coverage">Part of the diagnostic data is not available.</li><li v-for="issue in view.summary.data.issues" :key="issue">{{issues[issue]??issue}}</li></ul></details></template>
<details class="config"><summary>Diagnostic connection</summary><p>Local connection to the selected port and base: SSH user’s established psql, existing peer authentication or peer authentication is used ~/.pgpass. Passwords are not entered into the application. The database user must have CONNECT and access to pg_read_all_stats; the application does not grant rights or execute sudo.</p>
<form @submit.prevent="act(true)" @input="autosave.edited" @change="autosave.edited"><label class="check"><input v-model="config.enabled" type="checkbox">Enable diagnostic connections</label><label class="check"><input v-model="config.autoEndpoint" type="checkbox">Determine the address and port automatically</label><div class="fields"><label v-if="!config.autoEndpoint">Local IP or socket directory<UiInput v-model="config.endpoint" list="pg-endpoints" required/><datalist id="pg-endpoints"><option value="/var/run/postgresql"/><option value="/tmp"/><option value="127.0.0.1"/><option value="::1"/></datalist></label><label v-if="!config.autoEndpoint">port<UiInput v-model.number="config.port" type="number" min="1" max="65535" required/></label><label>Base<UiInput v-model="config.database" maxlength="63" required/></label><label>Role of DBD<UiInput v-model="config.user" maxlength="63" placeholder="By default, the SSH user"/></label><label>Check every one<UiInput v-model.number="config.intervalSeconds" type="number" unit="seconds" min="60" max="86400" required/></label><label>Expected streaming connections on primary<UiInput v-model.number="config.expectedPeers" type="number" min="0" max="64" required/></label></div><label class="check"><input v-model="config.expectReplica" type="checkbox">Streaming WAL receiver is expected to work on standby</label><p>Zero expected connections fit single primary. Changing host, port or base clears the history of this module so as not to mix the data of different connections.</p><span class="autosave-status" role="status">{{autosave.saving.value||autosave.pending.value?'Save it…':'Saved automatically'}}</span></form></details>
</section></template>
<style scoped>
.autosave-status{font-size:11px;color:var(--muted)}
.pg{border:0;margin:0;padding:0}.tag{display:inline-flex;align-items:center;padding:1px 9px;border-radius:20px;background:var(--subtle);color:var(--muted);white-space:nowrap}.tag.ok{background:var(--accent-bg);color:var(--success)}.tag.warn{background:var(--warning-bg);color:var(--warning)}.tag.crit{background:var(--danger-bg);color:var(--danger)}
.row{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 12px;align-items:center;font-size:13px;padding:10px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.row>*{min-width:0;max-width:100%;overflow-wrap:anywhere}.row small{flex-basis:100%;font-size:12px}
button{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:7px;padding:7px 10px;box-sizing:border-box;max-width:100%}button{cursor:pointer}button:hover:enabled{background:var(--hover)}button:disabled{opacity:.45;cursor:default}
p,li{overflow-wrap:anywhere;font-size:13px;line-height:1.6;color:var(--muted)}p{max-width:75ch}.version{margin:0 0 12px;font-size:12px}.problem{padding:10px 12px;background:var(--danger-bg);color:var(--danger);border-radius:7px;margin:0 0 8px}.notice{color:var(--warning)}
.metrics{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;margin:0 0 18px}.metrics>div{min-width:0;overflow-wrap:anywhere;background:var(--subtle);border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:2px}.metrics strong{font-size:22px;font-weight:450;letter-spacing:-.4px;font-variant-numeric:tabular-nums;min-width:0;max-width:100%;overflow-wrap:anywhere}.metrics small{font-size:11.5px}small{color:var(--muted);font-size:12px}
.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.fields>label{min-width:0}details{margin:8px 0;font-size:13px;color:var(--muted)}summary{cursor:pointer}.quality{background:var(--subtle);border-radius:10px;padding:10px 14px;margin-top:14px}.quality ul{margin:8px 0 2px}.config{margin-top:14px}article{overflow-wrap:anywhere}label{display:flex;flex-direction:column;gap:6px}.check{flex-direction:row;align-items:center}ul{padding-left:20px}.help p{margin:6px 0 0 14px}
button:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
@media(max-width:650px){.fields{grid-template-columns:1fr}}
</style>
